package top.ltfan.m3x.datastore

import androidx.datastore.core.Storage

/**
 * Describes a persisted data model: its identity, default value and codec.
 *
 * Implementations are usually generated by `datastore-processor` for classes annotated with
 * `@Store`. Keep the name, default value and codec stable throughout the definition's lifetime.
 * Within a [StoreHost], a name belongs to one definition instance; callers must reuse that instance
 * for subsequent requests.
 */
public interface StoreDefinition<T> {
    /** The name of this store, used as the cache key and the file name. */
    public val name: String

    /** The default value, used before the initial value is read. */
    public val defaultValue: T

    /** The codec used to encode and decode the value. */
    public val codec: StoreCodec<T>
}

/**
 * A byte-level codec contract.
 *
 * A codec translates between [T] and bytes; the model default value lives in
 * [StoreDefinition.defaultValue]. Consumers provide the CBOR / JSON / ... implementations, and the
 * processor glues them to the generated definitions.
 */
public interface StoreCodec<T> {
    /** Encodes [value] into bytes. */
    public fun encode(value: T): ByteArray

    /** Decodes [bytes] into a value. */
    public fun decode(bytes: ByteArray): T
}

/**
 * Turns a store name, its default value and a [StoreCodec] into a [Storage] backend.
 *
 * The default value is needed by file backends when the stored bytes are absent or empty, for
 * example `FileStorage` returns it for a missing file.
 *
 * Consumers provide the file backend (paths, file systems, platform contexts), for example
 * `FileStorage` on Android.
 */
public interface StoreFile {
    public fun <T> create(name: String, defaultValue: T, codec: StoreCodec<T>): Storage<T>
}
